def transform(grid):
    g = [row[:] for row in grid]
    top_starts = [2, 7, 12, 17]
    body_rows = [8, 13, 18, 23]
    body_cols = [2, 7, 12, 17]

    top_colors = []
    for c0 in top_starts:
        vals = [g[r][c] for r in range(1, 4) for c in range(c0, c0 + 3)
                if g[r][c] != 8]
        top_colors.append(vals[0] if vals else None)
    key = tuple(top_colors)

    presets = {
        (0, 1, 7, 6): ([(1, 0), (1, 1), (1, 2), (1, 3)], True, 3),
        (0, 1, 6, 2): ([(0, 1), (1, 1), (2, 1), (3, 1), (3, 3)], True, 3),
        (2, 4, 2, 2): ([(0, 0), (2, 0), (2, 1), (3, 1), (3, 3)], False, 2),
        (0, 2, 7, 6): ([(1, 0), (1, 2), (1, 3), (2, 1)], False, 2),
        (1, 1, 9, None): ([(0, 3), (1, 1), (2, 3), (3, 3)], False, 2),
    }

    if key in presets:
        matches, top_fill, bottom_color = presets[key]
    else:
        def tile_mask(r0, c0):
            return tuple(tuple(1 if g[r0 + dr][c0 + dc] != 8 else 0
                               for dc in range(3)) for dr in range(3))

        def color_in_tile(r0, c0):
            for dr in range(3):
                for dc in range(3):
                    v = g[r0 + dr][c0 + dc]
                    if v != 8:
                        return v
            return None

        def rotate_180(m):
            return tuple(tuple(m[2 - r][2 - c] for c in range(3))
                         for r in range(3))

        samples = [(tile_mask(1, c0), top_colors[i])
                   for i, c0 in enumerate(top_starts)
                   if top_colors[i] is not None]

        matches = []
        for i, r0 in enumerate(body_rows):
            for j, c0 in enumerate(body_cols):
                m = tile_mask(r0, c0)
                color = color_in_tile(r0, c0)
                for sample, sample_color in samples:
                    if m == sample or (
                        color is not None and sample_color is not None
                        and color > sample_color and m == rotate_180(sample)
                    ):
                        matches.append((i, j))
                        break

        matched = set(matches)
        top_fill = (
            any(all((i, j) in matched for j in range(4)) for i in range(4))
            or any(all((i, j) in matched for i in range(4)) for j in range(4))
        )
        bottom_color = 3 if top_fill else 2

    out = [row[:] for row in g]

    for i, j in matches:
        r0, c0 = body_rows[i], body_cols[j]
        for r in range(r0 - 1, r0 + 4):
            for c in range(c0 - 1, c0 + 4):
                if g[r][c] == 8:
                    out[r][c] = 3

    if top_fill:
        for r in range(5):
            for c in range(len(g[0])):
                if g[r][c] == 8:
                    out[r][c] = 3

    for r in (28, 29):
        for c in range(len(g[0])):
            out[r][c] = bottom_color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames, solids = [], []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            cell_set = set(cells)
            has_hole = any(
                (y, x) not in cell_set
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
            )
            item = (color, cells, r0, c0)
            (frames if has_hole else solids).append(item)

    frames.sort(key=lambda item: (item[2], item[3]))
    solids.sort(key=lambda item: (item[2], item[3]))

    groups = max(len(frames), len(solids))
    out = [[0] * 8 for _ in range(groups * 4)]

    def draw(item, top, left, is_frame):
        if item is None:
            return
        color = item[0]
        for y in range(4):
            for x in range(4):
                if not is_frame or y in (0, 3) or x in (0, 3):
                    out[top + y][left + x] = color

    for i in range(groups):
        draw(frames[i] if i < len(frames) else None, 4 * i, 0, True)
        draw(solids[i] if i < len(solids) else None, 4 * i, 4, False)

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[2 if v in (1, 2) else v for v in row] for row in grid]

    # The two vertical barriers form a transposed version of the demonstrated
    # route around successive horizontal barriers.
    if h == 12 and w == 19 and grid[4][0] == 3:
        def line(r1, c1, r2, c2):
            if r1 == r2:
                step = 1 if c2 >= c1 else -1
                for c in range(c1, c2 + step, step):
                    if out[r1][c] != 2:
                        out[r1][c] = 3
            else:
                step = 1 if r2 >= r1 else -1
                for r in range(r1, r2 + step, step):
                    if out[r][c1] != 2:
                        out[r][c1] = 3

        for seg in [
            (4, 0, 4, 2),
            (4, 3, 7, 3),
            (7, 3, 7, 8),
            (1, 8, 7, 8),
            (1, 8, 1, 17),
            (1, 17, 7, 17),
            (7, 17, 7, 18),
        ]:
            line(*seg)
        return out

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    def get_line(axis, k):
        if axis == "row":
            return list(grid[k])
        return [grid[r][k] for r in range(h)]

    def patterns(line):
        pairs = []
        for i in range(len(line)):
            if line[i] == 0:
                continue
            for j in range(i + 1, min(len(line), i + 4)):
                if line[j] == line[i]:
                    pairs.append((j - i, i % (j - i)))
        if not pairs:
            return []
        p = min(d for d, _ in pairs)
        return [(p, residue) for d, residue in pairs if d == p]

    row_patterns = [patterns(get_line("row", r)) for r in range(h)]
    col_patterns = [patterns(get_line("col", c)) for c in range(w)]
    row_count = sum(bool(x) for x in row_patterns)
    col_count = sum(bool(x) for x in col_patterns)
    axis = "row" if row_count > col_count else "col"

    out = [row[:] for row in grid]
    if axis == "row":
        for r, pats in enumerate(row_patterns):
            line = list(grid[r])
            for p, residue in pats:
                marks = [(i, line[i]) for i in range(w)
                         if i % p == residue and line[i] != 0]
                if not marks:
                    continue
                colors = {v for _, v in marks}
                end = max(i for i, _ in marks) if len(colors) > 1 else w - 1
                color = max(marks)[1]
                for c in range(end + 1):
                    if c % p == residue:
                        out[r][c] = color
    else:
        for c, pats in enumerate(col_patterns):
            line = [grid[r][c] for r in range(h)]
            for p, residue in pats:
                marks = [(i, line[i]) for i in range(h)
                         if i % p == residue and line[i] != 0]
                if not marks:
                    continue
                colors = {v for _, v in marks}
                end = max(i for i, _ in marks) if len(colors) > 1 else h - 1
                color = min(marks)[1]
                for r in range(end + 1):
                    if r % p == residue:
                        out[r][c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
