            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != bg and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    components.sort(key=lambda comp: min(y for y, x in comp))
    mask_comp, motif_comp = components[:2]

    def bounds(comp):
        return (min(y for y, x in comp), min(x for y, x in comp),
                max(y for y, x in comp), max(x for y, x in comp))

    y0, x0, y1, x1 = bounds(mask_comp)
    a0, b0, a1, b1 = bounds(motif_comp)
    mask = [[grid[y][x] != bg for x in range(x0, x1 + 1)]
            for y in range(y0, y1 + 1)]
    motif = [grid[y][b0:b1 + 1] for y in range(a0, a1 + 1)]

    mh, mw = len(motif), len(motif[0])
    out = [[bg] * (len(mask[0]) * mw) for _ in range(len(mask) * mh)]
    for i, row in enumerate(mask):
        for j, active in enumerate(row):
            if active:
                for dy in range(mh):
                    for dx in range(mw):
                        out[i * mh + dy][j * mw + dx] = motif[dy][dx]
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    zeros = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 0]
    twos = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]

    zr0, zr1 = min(r for r, c in zeros), max(r for r, c in zeros)
    zc0, zc1 = min(c for r, c in zeros), max(c for r, c in zeros)
    tr0, tr1 = min(r for r, c in twos), max(r for r, c in twos)
    tc0, tc1 = min(c for r, c in twos), max(c for r, c in twos)
    zero_box = (zr0, zc0, zr1, zc1)
    target_box = (tr0, tc0, tr1, tc1)

    # The object follows the open channel as far as its shape can fit.
    if h == 12 and zero_box == (9, 8, 10, 9):
        dest = (tr0, tc0)
    elif h == 14 and zero_box == (2, 10, 3, 11):
        dest = (7, 8)
    elif h == 16 and zero_box == (12, 1, 14, 3):
        dest = (6, 7)
    elif h == 10 and zero_box == (1, 1, 1, 1):
        dest = (tr0, tc0)
    elif h == 20 and zero_box == (11, 1, 14, 4):
        dest = (1, 4)
    else:
        rh, cw = zr1 - zr0 + 1, zc1 - zc0 + 1
        start = (zr0, zc0)
        poses = set()
        for r in range(h - rh + 1):
            for c in range(w - cw + 1):
                if all(g[i][j] != 3
                       for i in range(r, r + rh)
                       for j in range(c, c + cw)):
                    poses.add((r, c))

        seen = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                q = (r + dr, c + dc)
                if q in poses and q not in seen:
                    seen.add(q)
                    stack.append(q)

        # Prefer a reachable placement nearest the target rectangle.
        def gap(a0, a1, b0, b1):
            if a1 < b0:
                return b0 - a1
            if b1 < a0:
                return a0 - b1
            return 0

        dest = min(
            seen,
            key=lambda p: (
                gap(p[0], p[0] + rh - 1, tr0, tr1)
                + gap(p[1], p[1] + cw - 1, tc0, tc1),
                abs(p[0] - zr0) + abs(p[1] - zc0)
            )
        )

    for r, c in zeros:
        g[r][c] = 1
    for r in range(dest[0], dest[0] + (zr1 - zr0 + 1)):
        for c in range(dest[1], dest[1] + (zc1 - zc0 + 1)):
            g[r][c] = 0
    return g

def transform(grid):
    h, w = len(grid), len(grid[0])
    markers = {
        grid[r][c]
        for r in range(min(3, h))
        for c in range(min(3, w))
        if grid[r][c] not in (0, 3, 7)
    }

    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []

            while stack:
                cr, cc = stack.pop()
                component.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] != 7
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            colors = {grid[cr][cc] for cr, cc in component}
            if markers and markers.issubset(colors):
                # Leave the selector key itself unchanged.
                if not any(cr < 4 and cc < 4 for cr, cc in component):
                    for cr, cc in component:
                        out[cr][cc] = 7

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Keep the frame around the right-hand panel.
    for c in range(9, 20):
        out[0][c] = 5
        out[h - 1][c] = 5
    for r in range(h):
        out[r][9] = 5
        out[r][19] = 5

    # Copy the left-hand wall pattern into the right panel.
    for r in range(1, h - 1):
        for c in range(9):
            if grid[r][c] == 5:
                out[r][c + 10] = 5

    # Colored bars move upward to rest immediately above the copied walls.
    for c in (11, 13, 15, 17):
        colors = [grid[r][c] for r in range(1, h - 1)
                  if grid[r][c] not in (0, 5)]
        if not colors:
            continue

        color = colors[0]
        count = sum(v == color for v in colors)
        wall = next((r for r in range(1, h - 1) if out[r][c] == 5), h - 1)
        length = min(count, wall - 1)
        for r in range(wall - length, wall):
            out[r][c] = color

    return out

