    h, w = len(grid), len(grid[0])
    n = (h - 4) // 2
    starts = list(range(0, w - n + 1, n + 1))
    starts = [s for s in starts if any(grid[h - 1][s:s + n])]

    templates = []
    template_colors = []
    labels = []
    for s in starts:
        tile = [row[s:s+n] for row in grid[:n]]
        templates.append(tile)
        vals = [v for row in tile for v in row if v != 0]
        template_colors.append(max(set(vals), key=vals.count) if vals else 0)
        vals = [v for v in grid[h-1][s:s+n] if v != 0]
        labels.append(vals[0] if vals else 0)

    out = [[0] * (n*n) for _ in range(n*n)]
    for i, s in enumerate(starts):
        lower = [row[s:s+n] for row in grid[n+1:2*n+1]]
        vals = [v for row in lower for v in row if v != 0]
        if not vals:
            continue
        c = max(set(vals), key=vals.count)
        j = template_colors.index(c) if c in template_colors else i
        color = labels[j]
        for r in range(n):
            for col in range(n):
                if lower[r][col] != 0:
                    for tr in range(n):
                        for tc in range(n):
                            if templates[j][tr][tc] != 0:
                                out[r*n+tr][col*n+tc] = color
    return out

