def transform(grid):
    from collections import Counter
    from itertools import permutations

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the separate colored patches.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            objects.append({
                "color": color, "cells": cells, "r": r0, "c": c0,
                "h": r1-r0+1, "w": c1-c0+1
            })

    def hole_components(obj):
        # Count connected groups of background-colored cells inside the patch.
        holes = {
            (y, x)
            for y in range(obj["r"], obj["r"] + obj["h"])
            for x in range(obj["c"], obj["c"] + obj["w"])
            if grid[y][x] == bg
        }
        count = 0
        while holes:
            count += 1
            start = holes.pop()
            stack = [start]
            while stack:
                y, x = stack.pop()
                for p in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if p in holes:
                        holes.remove(p)
                        stack.append(p)
        return count

    square_sizes = sorted({
        o["h"] for o in objects if o["h"] == o["w"]
    })
    if len(square_sizes) < 2:
        return grid

    frame_side = max(square_sizes)
    motif_side = max(s for s in square_sizes if s < frame_side)
    frames = sorted(
        [o for o in objects if o["h"] == frame_side and o["w"] == frame_side],
        key=lambda o: (o["r"], o["c"])
    )
    motifs = [
        o for o in objects if o["h"] == motif_side and o["w"] == motif_side
    ]
    if not frames or len(frames) != len(motifs) or frame_side != motif_side + 2:
        return grid

    fholes = [hole_components(o) for o in frames]
    mholes = [hole_components(o) for o in motifs]

    # Pair patches whose missing-cell patterns have the same number of
    # connected components; use proximity to break any ties.
    best_perm, best_cost = None, None
    for perm in permutations(range(len(motifs))):
        cost = 0
        for i, j in enumerate(perm):
            cost += 10000 * abs(fholes[i] - mholes[j])
            fy = frames[i]["r"] + frame_side / 2
            fx = frames[i]["c"] + frame_side / 2
            my = motifs[j]["r"] + motif_side / 2
            mx = motifs[j]["c"] + motif_side / 2
            cost += abs(fy - my) + abs(fx - mx)
        if best_cost is None or cost < best_cost:
            best_cost, best_perm = cost, perm

    tile = frame_side
    frame_rows = sorted({o["r"] for o in frames})
    frame_cols = sorted({o["c"] for o in frames})
    out = [[bg] * (len(frame_cols) * tile)
           for _ in range(len(frame_rows) * tile)]

    for i, frame in enumerate(frames):
        motif = motifs[best_perm[i]]
        tr = frame_rows.index(frame["r"]) * tile
        tc = frame_cols.index(frame["c"]) * tile
        for y in range(tile):
            for x in range(tile):
                if y == 0 or x == 0 or y == tile - 1 or x == tile - 1:
                    out[tr+y][tc+x] = frame["color"]
                else:
                    v = grid[motif["r"] + y - 1][motif["c"] + x - 1]
                    out[tr+y][tc+x] = (
                        motif["color"] if v != bg else frame["color"]
                    )
    return out

