                comp = []
                for y, x in q:
                    comp.append((y, x))
                    for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                        if (rlo <= yy < rhi and clo <= xx < chi
                                and grid[yy][xx] == color
                                and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            q.append((yy, xx))
                result.append(comp)
        return result

    def bounds(comp):
        return (min(r for r, c in comp), max(r for r, c in comp),
                min(c for r, c in comp), max(c for r, c in comp))

    def shape_key(comp):
        pts0 = [(r - min(y for y, x in comp),
                 c - min(x for y, x in comp)) for r, c in comp]
        forms = []
        for reflection in (1, -1):
            for turns in range(4):
                pts = []
                for y, x in pts0:
                    x *= reflection
                    for _ in range(turns):
                        y, x = x, -y
                    pts.append((y, x))
                my = min(y for y, x in pts)
                mx = min(x for y, x in pts)
                forms.append(tuple(sorted((y-my, x-mx) for y, x in pts)))
        return min(forms)

    # Find the large two-color rectangular template, whose border is its
    # background color.
    candidates = []
    for color in set(v for row in grid for v in row):
        for comp in components(color):
            r0, r1, c0, c1 = bounds(comp)
            rh, rw = r1-r0+1, c1-c0+1
            if rh < 7 or rw < 7:
                continue
            if not all(grid[r0][c] == color and grid[r1][c] == color
                       for c in range(c0, c1+1)):
