    out = [grid[r][c0:chi] for r in range(r0, rhi)]
    for comp in components(marker, r0, rhi, c0, chi):
        key = shape_key(comp)
        if key in votes:
            color = votes[key].most_common(1)[0][0]
            for r, c in comp:
                out[r-r0][c-c0] = color

    return out

