        for dr, dc in directions:
            pos = set(piece)
            steps = 0
            while True:
                nxt = shifted(pos, dr, dc)
                if any(r < 0 or r >= h or c < 0 or c >= w for r, c in nxt):
                    break
                hits = {occupied[p] for p in nxt if p in occupied}
                if hits:
                    for target in hits:
                        r0, r1, c0, c1 = boxes[target]
                        fully_inside = all(
                            r0 <= r <= r1 and c0 <= c <= c1 for r, c in pos
                        )
                        has_interior = any(
                            r0 < r < r1 and c0 < c < c1 for r, c in pos
                        )
                        if fully_inside and has_interior:
                            candidates.append((steps, target, dr, dc))
                    break
                pos = nxt
                steps += 1

        if candidates:
            steps, target, dr, dc = min(candidates, key=lambda x: x[0])
            plans.append((steps, idx, dr, dc))

    out = [row[:] for row in grid]
    for piece in pieces:
        for r, c in piece:
            out[r][c] = bg

    trails = set()
    destinations = set()
    for steps, idx, dr, dc in plans:
        pos = set(pieces[idx])
        for _ in range(steps):
            trails.update(pos)
            pos = shifted(pos, dr, dc)
        destinations.update(pos)

    for r, c in trails - destinations:
        if (r, c) not in occupied:
            out[r][c] = 0
    for r, c in destinations:
        out[r][c] = 2

    return out

