def transform(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])

    def dominant(line):
        counts = {}
        for x in line:
            counts[x] = counts.get(x, 0) + 1
        value = max(counts, key=counts.get)
        return counts[value] / len(line)

    protected_rows = [dominant(row) >= 0.82 for row in g]
    protected_cols = [
        dominant([g[r][c] for r in range(R)]) >= 0.82
        for c in range(C)
    ]

    # For each cell, retain the strongest periodic-pattern suggestion
    # independently from its row and column.
    row_votes = [[{} for _ in range(C)] for _ in range(R)]
    col_votes = [[{} for _ in range(C)] for _ in range(R)]

    def scan_line(values, coords, votes):
        n = len(values)
        for start in range(n):
            for end in range(start + 6, n + 1):
                length = end - start
                for period in range(2, min(8, length // 3) + 1):
                    groups = [[] for _ in range(period)]
                    for k in range(length):
                        groups[k % period].append(values[start + k])

                    modes = []
                    ratios = []
                    errors = 0
                    valid = True
                    for group in groups:
                        counts = {}
                        for value in group:
                            counts[value] = counts.get(value, 0) + 1
                        mode = max(counts, key=counts.get)
                        ratio = counts[mode] / len(group)
                        if len(group) < 3 or ratio < 0.62:
                            valid = False
                            break
                        modes.append(mode)
                        ratios.append(ratio)
                        errors += len(group) - counts[mode]

                    if not valid or len(set(modes)) < 2:
                        continue
                    if errors == 0 or errors > max(1, int(0.18 * length)):
                        continue

                    confidence = (
                        (length / period)
                        * min(ratios)
                        * (1.0 - errors / length)
                    )
                    if confidence < 2.5:
                        continue

                    for k in range(length):
                        r, c = coords[start + k]
                        expected = modes[k % period]
                        if values[start + k] == expected:
                            continue
                        cell_votes = votes[r][c]
                        cell_votes[expected] = max(
                            cell_votes.get(expected, 0.0), confidence
                        )

    for r in range(R):
        scan_line(g[r], [(r, c) for c in range(C)], row_votes)

    for c in range(C):
        values = [g[r][c] for r in range(R)]
        scan_line(values, [(r, c) for r in range(R)], col_votes)

    for r in range(R):
        for c in range(C):
            if protected_rows[r] or protected_cols[c]:
                continue
            scores = {}
            for value, score in row_votes[r][c].items():
                scores[value] = scores.get(value, 0.0) + score
            for value, score in col_votes[r][c].items():
                scores[value] = scores.get(value, 0.0) + score

            if not scores:
                continue
            ranked = sorted(scores.items(), key=lambda item: item[1], reverse=True)
            value, best = ranked[0]
            second = ranked[1][1] if len(ranked) > 1 else 0.0
            if best >= 2.5 and best >= 1.2 * second:
                g[r][c] = value

    return g

from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
    runs_by_direction = []

    for dr, dc in directions:
        runs = []
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(cells) >= 2:
                    runs.append((color, cells))
        runs_by_direction.append(runs)

    idx = max(range(len(directions)),
              key=lambda i: sum(len(cells) for _, cells in runs_by_direction[i]))
    runs = runs_by_direction[idx]
    if not runs:
        return [row[:] for row in grid]

    dr, dc = directions[idx]
    if (dr, dc) == (0, 1):
        across = lambda p: p[0]
    elif (dr, dc) == (1, 0):
        across = lambda p: p[1]
    elif (dr, dc) == (1, 1):
        across = lambda p: p[0] - p[1]
    else:
        across = lambda p: p[0] + p[1]

    ordered = sorted(runs, key=lambda item: across(item[1][0]))
    target = len(ordered[len(ordered) // 2][1])

    starts = [cells[0] for _, cells in runs]
    ends = [cells[-1] for _, cells in runs]
    start_align = max(Counter(r * dr + c * dc for r, c in starts).values())
    end_align = max(Counter(r * dr + c * dc for r, c in ends).values())
    keep_start = start_align > end_align

    out = [row[:] for row in grid]
    for color, cells in runs:
        for r, c in cells:
            out[r][c] = bg
        ar, ac = cells[0] if keep_start else cells[-1]
        for k in range(target):
            if keep_start:
                r, c = ar + k * dr, ac + k * dc
            else:
                r, c = ar - k * dr, ac - k * dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The template color has a large bounding box containing exactly two colors.
    candidates = []
    for color in range(10):
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        if not pts:
            continue
        r0 = min(r for r, c in pts)
        r1 = max(r for r, c in pts)
        c0 = min(c for r, c in pts)
        c1 = max(c for r, c in pts)
        vals = {grid[r][c] for r in range(r0, r1 + 1)
                for c in range(c0, c1 + 1)}
        if len(vals) == 2 and color in vals:
            candidates.append(((r1 - r0 + 1) * (c1 - c0 + 1),
                               color, r0, r1, c0, c1, vals))

    if not candidates:
        return [row[:] for row in grid]

    _, pattern, r0, r1, c0, c1, vals = max(candidates)
    bg = next(v for v in vals if v != pattern)
    oh, ow = r1 - r0 + 1, c1 - c0 + 1
    out = [grid[r0 + r][:c1 + 1][c0:c1 + 1] for r in range(oh)]
    holes = {(r, c) for r in range(oh) for c in range(ow)
             if out[r][c] == bg}

    # Find the separate foreground objects outside the template.
    foreground = {
        (r, c): grid[r][c]
        for r in range(h) for c in range(w)
        if not (r0 <= r <= r1 and c0 <= c <= c1)
        and grid[r][c] != bg
    }
    seen = set()
    components = []
    for start in foreground:
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c, foreground[(r, c)]))
            for q in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if q in foreground and q not in seen:
                    seen.add(q)
                    stack.append(q)
        components.append(comp)

    # Group objects by their exact footprint; each footprint is a tile.
    groups = {}
    for comp in components:
        mr = min(r for r, c, v in comp)
        mc = min(c for r, c, v in comp)
        shape = tuple(sorted((r - mr, c - mc) for r, c, v in comp))
        groups.setdefault(shape, []).append((mr, mc, comp))

    hole_list = sorted(holes)
    if sum(len(shape) * len(items) for shape, items in groups.items()) != len(holes):
        return out

    shapes = list(groups)
    counts = [len(groups[s]) for s in shapes]
    placements = []
    bycell = {p: [] for p in holes}

    for ti, shape in enumerate(shapes):
        maxr = max(r for r, c in shape)
        maxc = max(c for r, c in shape)
        plist = []
        for ar in range(oh - maxr):
            for ac in range(ow - maxc):
                cells = [(ar + dr, ac + dc) for dr, dc in shape]
                if all(p in holes for p in cells):
                    mask = 0
                    for rr, cc in cells:
                        mask |= 1 << (rr * ow + cc)
                    pi = len(plist)
                    plist.append((mask, ar, ac))
                    for p in cells:
                        bycell[p].append((ti, pi))
        placements.append(plist)

    full = 0
    for r, c in holes:
        full |= 1 << (r * ow + c)

    failed = set()

    def solve(used, rem):
        if used == full:
            return [] if not any(rem) else None
        state = (used, tuple(rem))
        if state in failed:
            return None

        best = None
        best_opts = None
        for r, c in hole_list:
            bit = 1 << (r * ow + c)
            if used & bit:
                continue
            opts = []
            for ti, pi in bycell[(r, c)]:
                if rem[ti]:
                    mask, ar, ac = placements[ti][pi]
                    if not (mask & used):
                        opts.append((ti, pi))
            if not opts:
                failed.add(state)
                return None
            if best_opts is None or len(opts) < len(best_opts):
                best = (r, c)
                best_opts = opts
                if len(opts) == 1:
                    break

        best_opts.sort(key=lambda x: (
            -len(shapes[x[0]]),
            placements[x[0]][x[1]][1],
            placements[x[0]][x[1]][2],
            x[0]
        ))
        for ti, pi in best_opts:
            mask, ar, ac = placements[ti][pi]
            rem[ti] -= 1
            rest = solve(used | mask, rem)
            rem[ti] += 1
            if rest is not None:
                return [(ti, ar, ac)] + rest

        failed.add(state)
        return None

    solution = solve(0, counts[:])
    if solution is None:
        return out

    # Identical-shaped source objects map to their destination placements in
    # reading order.
    dests = {i: [] for i in range(len(shapes))}
    for ti, ar, ac in solution:
        dests[ti].append((ar, ac))
    for ti, shape in enumerate(shapes):
        srcs = sorted(groups[shape], key=lambda x: (x[0], x[1]))
        locs = sorted(dests[ti])
        for (mr, mc, comp), (ar, ac) in zip(srcs, locs):
            for r, c, value in comp:
                out[ar + r - mr][ac + c - mc] = value

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))
    tiles = []

    for r in range(1, h - 3):
        for c in range(1, w - 3):
            inner = grid[r][c]
            if inner == bg:
                continue
            if any(grid[i][j] != inner
                   for i in range(r, r + 3)
                   for j in range(c, c + 3)):
                continue
            border = grid[r - 1][c - 1]
            if border == bg or border == inner:
                continue
            good = True
            for i in range(r - 1, r + 4):
                for j in range(c - 1, c + 4):
                    if i in (r - 1, r + 3) or j in (c - 1, c + 3):
                        if grid[i][j] != border:
                            good = False
            if good:
                tiles.append([r - 1, c - 1, border, inner])

    def overlaps(a, nr, nc, b):
        return (nr < b[0] + 5 and nr + 5 > b[0] and
                nc < b[1] + 5 and nc + 5 > b[1])

    # Border 8 objects move left; border 2 objects move right.
    for _ in range(w * 2):
        moved = False
        order = sorted(
            range(len(tiles)),
            key=lambda k: (tiles[k][2] != 8,
                           tiles[k][1] if tiles[k][2] == 8 else -tiles[k][1])
        )
        for k in order:
            r, c, border, inner = tiles[k]
            dc = -1 if border == 8 else 1
            nc = c + dc
            if nc < 0 or nc + 5 > w:
                continue
            if any(j != k and overlaps(tiles[k], r, nc, tiles[j])
                   for j in range(len(tiles))):
                continue
            tiles[k][1] = nc
            moved = True
        if not moved:
            break

    out = [row[:] for row in grid]
    for r, c, _, _ in tiles:
        for i in range(r, r + 5):
            for j in range(c, c + 5):
                out[i][j] = bg

    for r, c, border, inner in tiles:
        for i in range(r, r + 5):
            for j in range(c, c + 5):
                out[i][j] = inner if r < i < r + 4 and c < j < c + 4 else border
    return out

def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    seen = set()
    pieces = []

    # Colored connected components are the movable pieces; adjacent 2s are ports.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            ports = set()
            for y, x in cells:
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2:
                        ports.add((ny,nx))
            pieces.append({"color": color, "cells": cells, "ports": ports})

    if not pieces:
        return [row[:] for row in grid]

    def normalize(p):
        allpts = p["cells"] | p["ports"]
        minr = min(y for y,x in allpts)
        minc = min(x for y,x in allpts)
        return {
            "color": p["color"],
            "cells": {(y-minr,x-minc) for y,x in p["cells"]},
            "ports": {(y-minr,x-minc) for y,x in p["ports"]},
            "origin": (minr,minc)
        }

    pieces = [normalize(p) for p in pieces]

    # The 4-piece is the fixed central piece.
    anchor = max((i for i,p in enumerate(pieces) if p["color"] == 4),
                 key=lambda i: len(pieces[i]["cells"]), default=0)
    positions = {anchor: pieces[anchor]["origin"]}

    def placed_points(i, pos):
        dr, dc = pos
        p = pieces[i]
        return ({(y+dr,x+dc) for y,x in p["cells"]},
                {(y+dr,x+dc) for y,x in p["ports"]})

    def valid(i, pos):
        cells, _ = placed_points(i, pos)
        for j, jp in positions.items():
            if i == j:
                continue
            other, _ = placed_points(j, jp)
            if cells & other:
                return False
        return True

    def candidates(i, placed):
        p = pieces[i]
        found = {}
        for j, jp in placed.items():
            q = pieces[j]
            if not p["ports"] or not q["ports"]:
                continue
            qports = {(y+jp[0],x+jp[1]) for y,x in q["ports"]}
            for py, px in p["ports"]:
                for qy, qx in qports:
                    pos = (qy-py, qx-px)
                    if pos in found:
                        continue
                    ports = {(y+pos[0],x+pos[1]) for y,x in p["ports"]}
                    overlap = len(ports & qports)
                    if overlap:
                        found[pos] = max(found.get(pos, 0), overlap)
        return found

    remaining = set(range(len(pieces))) - {anchor}
    # Grow the assembly by matching multiple ports whenever possible.
    while remaining:
        best = None
        for i in remaining:
            for pos, overlap in candidates(i, positions).items():
                if not valid(i, pos):
                    continue
                cells, _ = placed_points(i, pos)
                existing = set()
                for j, jp in positions.items():
                    cc, _ = placed_points(j, jp)
                    existing |= cc
                near = min((abs(y-a)+abs(x-b) for y,x in cells for a,b in existing),
                           default=0)
                # Prefer multi-port matches, then compact placement.
                score = (overlap, -near, -i)
                if best is None or score > best[0]:
                    best = (score, i, pos)
        if best is not None:
            _, i, pos = best
            positions[i] = pos
            remaining.remove(i)
            continue

        # If a piece has no matching port pattern, place it compactly beside
        # the current assembly, preserving its orientation.
        i = min(remaining)
        existing = set()
        for j, jp in positions.items():
            cc, _ = placed_points(j, jp)
            existing |= cc
        bestpos, bestscore = None, None
        for dr in range(-h, h):
            for dc in range(-w, w):
                cells, _ = placed_points(i, (dr,dc))
                if not cells or min(y for y,x in cells) < 0 or max(y for y,x in cells) >= h:
                    continue
                if min(x for y,x in cells) < 0 or max(x for y,x in cells) >= w:
                    continue
                if not valid(i, (dr,dc)):
                    continue
                dist = min(abs(y-a)+abs(x-b) for y,x in cells for a,b in existing) if existing else 0
                score = (dist, abs(dr)+abs(dc))
                if bestscore is None or score < bestscore:
                    bestscore, bestpos = score, (dr,dc)
        positions[i] = bestpos if bestpos is not None else pieces[i]["origin"]
        remaining.remove(i)

    out = [[0]*w for _ in range(h)]
    allports = set()
    for i, pos in positions.items():
        cells, ports = placed_points(i, pos)
        for y, x in cells:
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = pieces[i]["color"]
        allports |= ports
    for y, x in allports:
        if 0 <= y < h and 0 <= x < w and out[y][x] == 0:
            out[y][x] = 2
    return out

